package bowling

import "errors"

// Game keeps track of the rolls in a game of bowling.
type Game struct {
	rolls        []int // every roll in the game, in order
	frame        int   // current frame, 0-9; 10 means the game is over
	remaining    int   // pins still standing on the lane
	tenthFrameRolls int // rolls taken in the tenth frame
}

// NewGame returns a new, unstarted game.
func NewGame() *Game {
	return &Game{remaining: 10}
}

// Roll records a throw that knocked down pins pins.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errors.New("Negative roll is invalid")
	}
	if pins > 10 {
		return errors.New("Pin count exceeds pins on the lane")
	}
	if g.frame == 10 {
		return errors.New("Cannot roll after game is over")
	}
	if pins > g.remaining {
		return errors.New("Pin count exceeds pins on the lane")
	}
	g.remaining -= pins
	g.rolls = append(g.rolls, pins)

	if g.frame < 9 {
		if g.remaining == 0 {
			g.frame++
			g.remaining = 10
		}
		return nil
	}

	// Tenth frame: a strike or spare earns a fill ball.
	g.tenthFrameRolls++
	if g.remaining == 0 {
		g.remaining = 10
	} else if g.tenthFrameRolls == 2 {
		g.frame = 10 // open tenth frame ends the game
	}
	if g.tenthFrameRolls == 3 {
		g.frame = 10
	}
	return nil
}

// Score returns the total score for a completed game.
func (g *Game) Score() (int, error) {
	if g.frame != 10 {
		return 0, errors.New("Score cannot be taken until the end of the game")
	}
	score := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case g.rolls[i] == 10: // strike
			score += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		case g.rolls[i]+g.rolls[i+1] == 10: // spare
			score += 10 + g.rolls[i+2]
			i += 2
		default: // open frame
			score += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return score, nil
}

